http:request.http:body:
#[output application/json --- {
	'type': vars.toApply.REQUEST_TYPE, key: vars.toApply.IDEMPOTENCY_KEY,
	(itemId: vars.toApply.ITEM_ID) if (vars.toApply.ITEM_ID != null),
	(provider: vars.toApply.PROVIDER_ABV) if (vars.toApply.PROVIDER_ABV != null),
	(quantity: vars.toApply.QTY as Number) if (vars.toApply.QTY != null)
}]

amqp:message.amqp:body:
#[output application/json --- {
	eventType: "correction.applied", requestId: vars.requestId, orderId: vars.toApply.ORDER_ID, customerId: vars.toApply.CUSTOMER_ID,
	"type": vars.toApply.REQUEST_TYPE,
	detail: {
		(itemId: vars.toApply.ITEM_ID) if (vars.toApply.ITEM_ID != null),
		(quantity: vars.toApply.QTY as Number) if (vars.toApply.QTY != null),
		(provider: vars.toApply.PROVIDER_ABV) if (vars.toApply.PROVIDER_ABV != null),
		(dispatchNoteId: vars.correctionResult.dispatchNote.dispatchNoteId) if (vars.correctionResult.dispatchNote.dispatchNoteId != null)
	},
	occurredAt: (now() >> "UTC") as String {format: "yyyy-MM-dd'T'HH:mm:ss'Z'"}
}]
